  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'সংহতিসমূহ খোলক, সুৰক্ষালৈ যাওক, তাৰ পিছত পাছৱৰ্ড বা দুটা-কাৰক সংলাপ ব্যৱহাৰ কৰক। দুটা-কাৰক বিতৰণে বিন্যাস কৰাৰ সময়ত ইমেইল বা ফোন সমৰ্থন কৰে।',
