  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'এই PlayHub মোতায়েনক এটা দৰ্শক, সৃষ্টিকৰ্তা, বা প্ৰশাসক হিচাপে ব্যৱহাৰ কৰাৰ বাবে নিয়মসমূহ।',
