  'Scheduled video release and reminders.' => 'নিৰ্ধাৰিত ভিডিঅ\' মুক্তি আৰু সোঁৱৰাই দিয়া।',
  'Scheduled videos' => 'নিৰ্ধাৰিত ভিডিঅ\'',
