  'Search for answers...' => 'উত্তৰৰ বাবে সন্ধান কৰক...',
  'Search help articles, topics, or questions...' => 'সহায়তা প্ৰবন্ধ, বিষয়, বা প্ৰশ্ন সন্ধান কৰক...',
  'Select a reason' => 'এটা কাৰণ বাছি লওক',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'এটা বা অধিক ভিডিঅ\' ফাইল নিৰ্ব্বাচন কৰক, প্ৰয়োজনীয় বিৱৰণ সুমুৱাওক, শ্ৰেণী আৰু ভাষা বাছক, এটা থাম্বনেইল যোগ কৰক, দৃশ্যমানতা বাছক, আৰু প্ৰকাশ কৰক। চাৰ্ভাৰে প্ৰচেছিং আৰম্ভ কৰাৰ আগতে ডাঙৰ ফাইলসমূহক টুকুৰা টুকুৰকৈ আপলোড কৰা হয়।',
  'Send a message and it will be saved for admins.' => 'এটা মেছেজ পঠাওক আৰু এডমিনৰ বাবে চেভ হৈ যাব।',
  'Send billing details to admin support for review.' => 'পৰ্যালোচনাৰ বাবে বিলিংৰ বিৱৰণ প্ৰশাসক সমৰ্থনলৈ প্ৰেৰণ কৰক।',
  'Send message' => 'বাৰ্তা প্ৰেৰণ কৰক',
  'Send order details through the refund popup.' => 'ৰিফাণ্ড পপআপৰ জৰিয়তে অৰ্ডাৰৰ বিৱৰণ প্ৰেৰণ কৰক।',
  'Send us a message' => 'আমালৈ এটা বাৰ্তা প্ৰেৰণ কৰক',
  'Sending...' => 'Sending...',
  'Server configured' => 'চাৰ্ভাৰ বিন্যাস কৰা হৈছে',
  'server records' => 'চাৰ্ভাৰ ৰেকৰ্ডসমূহ',
