  'session, token' => 'অধিবেশন, টোকেন',
  'Settings and login' => 'ছেটিংছ আৰু লগইন',
  'Short summary' => 'চমু সাৰাংশ',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'চাইন ইন আৰু একাউণ্ট, আলেখ্যন, পাছৱৰ্ড, জাননী, গোপনীয়তা, আৰু সৃষ্টিকৰ্তাৰ পছন্দসমূহৰ বাবে সংহতিসমূহ ব্যৱহাৰ কৰক। সৃষ্টিকৰ্তা আপলোড আৰু বিষয়বস্তুৰ সমস্যাসমূহে ভিডিঅ\'ৰ শিৰোনাম, চেনেল, ব্ৰাউজাৰ, আৰু আপল\'ড পৃষ্ঠাত দেখুওৱা যিকোনো প্ৰচেছিং ভুল অন্তৰ্ভুক্ত কৰিব লাগে।',
  'Sign in for account support' => 'একাউণ্ট সমৰ্থনৰ বাবে চাইন ইন কৰক',
  'Signed in' => 'চাইন ইন কৰা হৈছে',
  'Start uploading' => 'আপলোড আৰম্ভ কৰক',
  'Still can’t find an answer?' => 'এতিয়াও উত্তৰ বিচাৰি পোৱা নাই?',
  'Stored for admins' => 'এডমিনৰ বাবে সংৰক্ষণ কৰা হৈছে',
  'Stores language, theme, and interface preferences.' => 'ভাষা, থিম, আৰু আন্তঃপৃষ্ঠ পছন্দসমূহ সংৰক্ষণ কৰে।',
  'Studio, playlists, analytics, channels.' => 'ষ্টুডিঅ\', প্লেলিষ্ট, বিশ্লেষণ, চেনেল।',
  'Submit a billing or refund message to admin support.' => 'প্ৰশাসক সমৰ্থনলৈ বিলিং বা ধন ঘূৰাই দিয়া বাৰ্তা জমা দিয়ক।',
  'Submit refund request' => 'ধন ঘূৰাই দিয়াৰ অনুৰোধ জমা দিয়ক',
  'Submit request' => 'অনুৰোধ জমা দিয়ক',
  'Subscription cancellation' => 'চাবস্ক্ৰিপচন বাতিল কৰা হৈছে',
  'Support dashboard' => 'ডেচব\'ৰ্ড সমৰ্থন কৰে',
  'System status' => 'চিস্টেমৰ অৱস্থা',
  'Table' => 'টেবুল',
  'Taxonomies' => 'শ্ৰেণীবিভাজন',
  'Technical issue' => 'কাৰিকৰী বিষয়',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'বৰ্তমান PlayHub API আৰু আপল\'ড কাৰ্য্যপ্ৰবাহৰ সৈতে সংহতিসমূহৰ বাবে কাৰিকৰী টোকাসমূহ।',
  'Tell us more about your question or request...' => 'আপনার প্রশ্ন বা অনুরোধ সম্পর্কে আমাদের আরো কওক...',
  'Terms of Use' => 'ব্যৱহাৰৰ চৰ্তসমূহ',
  'The configured' => 'বিন্যাস কৰা হৈছে',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'ডেভেলপাৰ পৃষ্ঠা লাইভ Laravel বেকএণ্ডৰ সৈতে সংযুক্ত: পথ তথ্য, ডাটাবেইচ গণনা, আপল\'ড সীমা, আৰু প্লেটফৰ্ম মেটাডাটা /api/ডেভেলপাৰৰ পৰা লোড কৰা হয়।',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'ফ্ৰন্টএণ্ডে পছন্দসমূহ যেনে নিৰ্বাচিত ভাষা, থিম, প্লেবেক শাৰী, অগ্ৰগতি চাওক, আৰু আন্তঃপৃষ্ঠ অৱস্থা সংৰক্ষণ কৰে যাতে অভিজ্ঞতা পৃষ্ঠা নেভিগেচন আৰু পুনৰ লোডসমূহৰ মাজেৰে সামঞ্জস্যপূৰ্ণ থাকে।',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'প্ৰচেছিং কাৰ্য্যই ৰেণ্ডিংসমূহ এনকোড কৰে, প্ৰয়োজনৰ সময়ত থাম্বনেইলসমূহ সৃষ্টি কৰে, কেপচনসমূহ সংৰক্ষণ কৰে, আৰু প্ৰচেছিং সম্পূৰ্ণ হোৱাৰ সময়ত ভিডিঅ\'সমূহ প্ৰস্তুত চিহ্নিত কৰে। ভৱিষ্যতৰ নিৰ্ধাৰিত ভিডিঅ’সমূহ নিৰ্ধাৰিত ব্যক্তিয়ে মুকলি নকৰালৈকে ব্যক্তিগত হৈ থাকে।',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'আপল\'ড চিস্টেম ডাটাবেইচ-বেকড, API ৰ পৰা শ্ৰেণী আৰু ভাষাসমূহ সমৰ্থন কৰে, আপলোড কৰা ভিডিঅ\'সমূহ প্ৰক্ৰিয়া কৰে, থাম্বনেইল আৰু কেপচনসমূহ সংৰক্ষণ কৰে, আৰু নিৰ্ধাৰিত বিষয়বস্তু ইয়াৰ মুক্তিৰ সময়লৈকে ব্যক্তিগত ৰাখে।',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'এই পৃষ্ঠাই ব্যাখ্যা কৰে যে কেনেকৈ PlayHub-এ অধিবেশন, সুৰক্ষা, পছন্দ, প্লেবেক, আৰু প্ৰমাণীকৃত বৈশিষ্ট্যসমূহৰ বাবে কুকীজ আৰু ব্ৰাউজাৰ সংৰক্ষণ ব্যৱহাৰ কৰে৷',
  'Ticket source' => 'টিকটৰ উৎস',
  'Top content categories' => 'শীৰ্ষ বিষয়বস্তুৰ শ্ৰেণীসমূহ',
  'Topic' => 'বিষয়',
  'Transaction / invoice' => 'লেনদেন / চালান',
  'Transaction / invoice ID' => 'লেনদেন / চালান আইডি',
  'Unable to send message.' => 'বাৰ্তা প্ৰেৰণ কৰিব পৰা নাই।',
  'Unable to submit refund request.' => 'ধন ঘূৰাই দিয়াৰ অনুৰোধ জমা দিব পৰা নাই।',
  'Understanding admin support tickets' => 'এডমিন সমৰ্থন টিকট বুজি পোৱা',
  'Upload and processing help' => 'আপলোড আৰু প্ৰচেছিং সহায়',
  'Upload chunks' => 'টুকুৰা আপলোড কৰক',
  'Upload issues' => 'আপলোডৰ সমস্যা',
  'Upload languages' => 'ভাষাসমূহ আপলোড কৰক',
  'Upload limit' => 'আপলোডৰ সীমা',
  'Upload options' => 'আপলোড বিকল্পসমূহ',
  'Upload or processing' => 'আপল\'ড বা প্ৰচেছিং',
  'Upload page' => 'পৃষ্ঠা আপলোড কৰক',
  'Upload pipeline' => 'পাইপলাইন আপলোড কৰক',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'আপল\'ড, চাওক, চাবস্ক্ৰাইব, মধ্যমীয়া, আৰু লাইভ PlayHub ডাটাৰ সৈতে নিৰ্মাণ কৰক।',
  'Uploaded videos' => 'আপলোড কৰা ভিডিঅ\'',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'আপলোড কৰা ভিডিঅ\'সমূহ প্লেযোগ্য ৰেণ্ডিচনত এনকোড কৰা হয়। প্ৰচেছিং সময় নথিপত্ৰৰ আকাৰ, সময়কাল, চাৰ্ভাৰ লোড, আৰু শাৰীৰ অৱস্থাৰ ওপৰত নিৰ্ভৰ কৰে। আপলোড পৃষ্ঠা আৰু সৃষ্টিকৰ্তা ষ্টুডিঅ\'ই ভিডিঅ\' ৰেকৰ্ডৰ পৰা প্ৰকৃত প্ৰচেছিং অৱস্থা দেখুৱায়।',
  'Uploads, scheduling, and processing are available.' => 'আপল\'ড, সময়সূচী, আৰু প্ৰচেছিং উপলব্ধ।',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => '/api/videos, চেনেল শেষবিন্দুসমূহ, আৰু সৃষ্টিকৰ্তা কাৰ্য্যপ্ৰবাহসমূহৰ বাবে প্ৰমাণীকৃত পথসমূহ ব্যৱহাৰ কৰক।',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'ভিডিঅ\' আৰু মন্তব্যৰ বাবে বিল্ট-ইন প্ৰতিবেদন কাৰ্য্যসমূহ ব্যৱহাৰ কৰক যাতে প্ৰশাসকসকলে সঠিক বিষয়বস্তুৰ উল্লেখ লাভ কৰে। প্ৰশাসক ডেচব\'ৰ্ড পৃষ্ঠাসমূহে ব্যৱহাৰকাৰী, বিষয়বস্তু, প্ৰতিবেদন, মুদ্ৰাকৰণ, বিশ্লেষণ, সমৰ্থন, ভূমিকা, আৰু চিস্টেম সংহতিসমূহৰ বাবে লাইভ ডাটাবেইচ তথ্য ব্যৱহাৰ কৰে।',
  'Use Contact Us' => 'আমাৰ সৈতে যোগাযোগ কৰক ব্যৱহাৰ কৰক',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'সাধাৰণ API অনুৰোধসমূহৰ বাবে JSON আৰু নথিপত্ৰ আপল\'ডসমূহৰ বাবে FormData ব্যৱহাৰ কৰক। বৈধকৰণ বাইপাছ নকৰিব: শ্ৰেণী আৰু ভাষাসমূহ ডাটাবেইচ IDসমূহ, দৃশ্যমানতা ৰাজহুৱা, তালিকাভুক্ত নোহোৱা, বা ব্যক্তিগতত সীমিত, আৰু কেপচনসমূহে SRT, VTT, বা TXT নথিপত্ৰসমূহ গ্ৰহণ কৰে।',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'আপোনাৰ আলেখ্যন, সুৰক্ষা, পাছৱৰ্ড, দুটা-কাৰক বিতৰণ, ডিভাইচসমূহ, পছন্দসমূহ, আৰু অধিসূচনা বিকল্পসমূহ আপডেইট কৰিবলে সংহতিসমূহ ব্যৱহাৰ কৰক। যদি আপুনি আপোনাৰ একাউণ্টত প্ৰৱেশ কৰিব নোৱাৰে, প্ৰৱেশ প্ৰবাহ ব্যৱহাৰ কৰক আৰু একাউণ্ট ইমেইল চাইট প্ৰশাসকক প্ৰদান কৰক।',
  'Use the contact form' => 'যোগাযোগ প্ৰ-পত্ৰ ব্যৱহাৰ কৰক',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'ভিডিঅ\', মন্তব্য, আৰু সম্প্ৰদায়ৰ পোষ্টসমূহত প্ৰতিবেদন কাৰ্য্যসমূহ ব্যৱহাৰ কৰক যাতে প্ৰশাসকসকলে সঠিক বিষয়বস্তুৰ উল্লেখ লাভ কৰে।',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'ভিডিঅ\', মন্তব্য, আৰু সম্প্ৰদায়ৰ পোষ্টসমূহত প্ৰতিবেদন কাৰ্য্যসমূহ ব্যৱহাৰ কৰক যেতিয়া বিষয়বস্তুৱে প্লেটফৰ্মৰ নিয়মসমূহ উলংঘা কৰিব পাৰে। এই প্ৰতিবেদনসমূহ প্ৰকৃত বিষয়বস্তু ৰেকৰ্ডৰ সৈতে বান্ধ খাই থাকে আৰু এটা সাধাৰণ বাৰ্তাতকৈ ভাল কাৰণ প্ৰশাসকে সঠিক বস্তুটো পৰ্যালোচনা কৰিব পাৰে।',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'একাউণ্ট সহায়, বিষয়বস্তু প্ৰতিবেদন, কাৰিকৰী সমস্যা, আৰু প্ৰশাসকৰ অনুৰোধৰ বাবে সঠিক PlayHub চেনেল ব্যৱহাৰ কৰক।',
  'Video categories' => 'ভিডিঅ\' শ্ৰেণীসমূহ',
  'Video for everyone. Built for creators and viewers.' => 'সকলোৰে বাবে ভিডিঅ\'। প্ৰকৃত প্লেটফৰ্ম ডাটাৰ পৰা নিৰ্মিত।',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'ভিডিঅ\' আপলোড, সময়সূচী, থাম্বনেইল, আৰু প্ৰচেছিং সমস্যাসমূহ।',
  'Videos, thumbnails, captions, processing.' => 'ভিডিঅ\', থাম্বনেইল, কেপচন, প্ৰচেছিং।',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'দৰ্শকে শ্ৰেণীসমূহ ব্ৰাউজ কৰিব পাৰে, ভিডিঅ\' সন্ধান কৰিব পাৰে, বিষয়বস্তু চাব পাৰে, চেনেলসমূহ চাবস্ক্ৰাইব কৰিব পাৰে, পিছত চাবলৈ ভিডিঅ\'সমূহ সংৰক্ষণ কৰিব পাৰে, মন্তব্য কৰিব পাৰে, জাননী লাভ কৰিব পাৰে, আৰু ভাষা আৰু অভিগম্যতা পছন্দসমূহ পৰিচালনা কৰিব পাৰে।',
  'Viewing and community help' => 'দৰ্শন আৰু সম্প্ৰদায়ৰ সহায়',
  'Waiting for backend endpoint inventory.' => 'বেকএণ্ড এণ্ডপইণ্ট ইনভেণ্টৰীৰ বাবে অপেক্ষা কৰি আছে।',
  'We’re here to help.' => 'আমি ইয়াত সহায় কৰিবলৈ আহিছো৷',
  'What is PlayHub?' => 'প্লেহাব কি?',
  'What PlayHub does' => 'প্লেহাবে কি কৰে',
  'Where do contact messages go?' => 'যোগাযোগ বাৰ্তা ক\'লৈ যায়?',
  'Why is my video still processing?' => 'মোৰ ভিডিঅ\'টো এতিয়াও কিয় প্ৰচেছিং হৈ আছে?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'হয়। আপল\'ড পৃষ্ঠাত স্থানীয় সময়সূচী তাৰিখ আৰু সময় ক্ষেত্ৰ ব্যৱহাৰ কৰক। বেকএণ্ডে scheduled_at সংৰক্ষণ কৰে, ভিডিঅ\' প্ৰক্ৰিয়া কৰে, তাৰিখ ভৱিষ্যতে থকাৰ সময়ত ইয়াক ব্যক্তিগত ৰাখে, আৰু ইয়াক মুকলি কৰে যেতিয়া Laravel সূচীকাৰী নিৰ্ধাৰিত সময়ৰ পিছত চলি থাকে।',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'হয়। আপল\'ডত স্থানীয় সময়সূচী ক্ষেত্ৰ ব্যৱহাৰ কৰক। বেকএণ্ডে scheduled_at সংৰক্ষণ কৰে আৰু সময়সূচী সময় পোৱাৰ পিছত প্ৰক্ৰিয়া কৰাৰ পিছত ভিডিঅ\' মুকলি কৰে।',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'আপুনি অতিথি হিচাপে ব্ৰাউজ কৰি আছে। একাউণ্ট-নিৰ্দিষ্ট সঁজুলিসমূহ অভিগম কৰিবলৈ চাইন ইন কৰক।',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'আপোনাৰ একাউণ্টৰ প্ৰমাণপত্ৰ, আলেখ্যন কাৰ্য্যকলাপ, আপলোড কৰা বিষয়বস্তু, মন্তব্য, বাৰ্তা, আৰু আপোনাৰ একাউণ্টৰ পৰা কৰা যিকোনো সৃষ্টিকৰ্তা বা প্ৰশাসকৰ কাৰ্য্যৰ বাবে আপুনি দায়বদ্ধ। শক্তিশালী পাছৱৰ্ড ব্যৱহাৰ কৰক আৰু দুটা-কাৰক প্ৰদান পদ্ধতিসমূহ বৰ্তমান ৰাখক।',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'আপুনি আপোনাৰ ব্ৰাউজাৰ ছেটিংছত ব্ৰাউজাৰ কুকীজ আৰু স্থানীয় সংৰক্ষণ পৰিষ্কাৰ কৰিব পাৰে। প্ৰয়োজনীয় সংৰক্ষণ পৰিষ্কাৰ কৰিলে আপুনি চাইন আউট কৰিব পাৰে, ভাষা/থিম পছন্দসমূহ পুনৰায় সেট কৰিব পাৰে, স্থানীয় প্লেবেক অৱস্থা আঁতৰাব পাৰে, আৰু আপুনি পুনৰ লগ ইন কৰাৰ প্ৰয়োজন হব পাৰে।',
  'You receive a response by email.' => 'আপুনি ইমেইলযোগে সঁহাৰি লাভ কৰে।',
  'You’re in control' => 'আপুনি নিয়ন্ত্ৰণত আছে৷',
  'Your choices' => 'আপোনাৰ পছন্দ',
